Here is the commit message:
bpf: Fix ld_{abs,ind} failure path analysis in subprogs

Usage of ld_{abs,ind} instructions got extended into subprogs some time
ago via commit 09b28d76eac4 ("bpf: Add abnormal return checks."). These
are only allowed in subprograms when the latter are BTF annotated and
have scalar return types.

The code generator in bpf_gen_ld_abs() has an abnormal exit path (r0=0 +
exit) from legacy cBPF times. While the enforcement is on scalar return
types, the verifier must also simulate the path of abnormal exit if the
packet data load via ld_{abs,ind} failed.

This is currently not the case. Fix it by having the verifier simulate
both success and failure paths, and extend it in similar ways as we do
for tail calls. The success path (r0=unknown, continue to next insn) is
pushed onto stack for later validation and the r0=0 and return to the
caller is done on the fall-through side.

Fixes: 09b28d76eac4 ("bpf: Add abnormal return checks.")
Reported-by: STAR Labs SG <info@starlabs.sg>
Signed-off-by: Daniel Borkmann <daniel@iogearbox.net>
Link: https://lore.kernel.org/r/20260408191242.526279-2-daniel@iogearbox.net
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The verifier's `check_ld_abs()` function did not simulate the abnormal exit path (setting `r0 = 0` and returning to the caller) for `ld_{abs,ind}` instructions inside subprograms, which the code generator emits as a hidden `BPF_EXIT` on packet load failure. This missing simulation caused the verifier to only explore the success path, leaving the failure path unaccounted for, potentially allowing unsafe programs to pass verification.

Here is the patch:
  */
 static int check_ld_abs(struct bpf_verifier_env *env, struct bpf_insn *insn)
 {
 	struct bpf_reg_state *regs = cur_regs(env);
 	static const int ctx_reg = BPF_REG_6;
 	u8 mode = BPF_MODE(insn->code);
 	int i, err;

 	if (!may_access_skb(resolve_prog_type(env->prog))) {
 		verbose(env, "BPF_LD_[ABS|IND] instructions not allowed for this program type\n");
 		return -EINVAL;
 	}

 	if (!env->ops->gen_ld_abs) {
 		verifier_bug(env, "gen_ld_abs is null");
 		return -EFAULT;
 	}

 	if (insn->dst_reg != BPF_REG_0 || insn->off != 0 ||
 	    BPF_SIZE(insn->code) == BPF_DW ||
 	    (mode == BPF_ABS && insn->src_reg != BPF_REG_0)) {
 		verbose(env, "BPF_LD_[ABS|IND] uses reserved fields\n");
 		return -EINVAL;
 	}

 	/* check whether implicit source operand (register R6) is readable */
 	err = check_reg_arg(env, ctx_reg, SRC_OP);
 	if (err)
 		return err;

 	/* Disallow usage of BPF_LD_[ABS|IND] with reference tracking, as
 	 * gen_ld_abs() may terminate the program at runtime, leading to
 	 * reference leak.
 	 */
 	err = check_resource_leak(env, false, true, "BPF_LD_[ABS|IND]");
 	if (err)
 		return err;

 	if (regs[ctx_reg].type != PTR_TO_CTX) {
 		verbose(env,
 			"at the time of BPF_LD_ABS|IND R6 != pointer to skb\n");
 		return -EINVAL;
 	}

 	if (mode == BPF_IND) {
 		/* check explicit source operand */
 		err = check_reg_arg(env, insn->src_reg, SRC_OP);
 		if (err)
 			return err;
 	}

 	err = check_ptr_off_reg(env, &regs[ctx_reg], ctx_reg);
 	if (err < 0)
 		return err;

 	/* reset caller saved regs to unreadable */
 	for (i = 0; i < CALLER_SAVED_REGS; i++) {
 		mark_reg_not_init(env, regs, caller_saved[i]);
 		check_reg_arg(env, caller_saved[i], DST_OP_NO_MARK);
 	}

 	/* mark destination R0 register as readable, since it contains
 	 * the value fetched from the packet.
 	 * Already marked as written above.
 	 */
 	mark_reg_unknown(env, regs, BPF_REG_0);
 	/* ld_abs load up to 32-bit skb data. */
 	regs[BPF_REG_0].subreg_def = env->insn_idx + 1;
+	/*
+	 * See bpf_gen_ld_abs() which emits a hidden BPF_EXIT with r0=0
+	 * which must be explored by the verifier when in a subprog.
+	 */
+	if (env->cur_state->curframe) {
+		struct bpf_verifier_state *branch;
+
+		mark_reg_scratched(env, BPF_REG_0);
+		branch = push_stack(env, env->insn_idx + 1, env->insn_idx, false);
+		if (IS_ERR(branch))
+			return PTR_ERR(branch);
+		mark_reg_known_zero(env, regs, BPF_REG_0);
+		err = prepare_func_exit(env, &env->insn_idx);
+		if (err)
+			return err;
+		env->insn_idx--;
+	}
 	return 0;
 }

 }

-static int visit_tailcall_insn(struct bpf_verifier_env *env, int t)
+/*
+ * Instructions that can abnormally return from a subprog (tail_call
+ * upon success, ld_{abs,ind} upon load failure) have a hidden exit
+ * that the verifier must account for.
+ */
+static int visit_abnormal_return_insn(struct bpf_verifier_env *env, int t)
 {
 	static struct bpf_subprog_info *subprog;
 	struct bpf_iarray *jt;

 	if (env->insn_aux_data[t].jt)
 		return 0;

 	jt = iarray_realloc(NULL, 2);
 	if (!jt)
 		return -ENOMEM;

 	subprog = bpf_find_containing_subprog(env, t);
 	jt->items[0] = t + 1;
 	jt->items[1] = subprog->exit_idx;
 	env->insn_aux_data[t].jt = jt;
 	return 0;
 }

  */
 static int visit_insn(int t, struct bpf_verifier_env *env)
 {
 	struct bpf_insn *insns = env->prog->insnsi, *insn = &insns[t];
 	int ret, off, insn_sz;

 	if (bpf_pseudo_func(insn))
 		return visit_func_call_insn(t, insns, env, true);

 	/* All non-branch instructions have a single fall-through edge. */
 	if (BPF_CLASS(insn->code) != BPF_JMP &&
 	    BPF_CLASS(insn->code) != BPF_JMP32) {
+		if (BPF_CLASS(insn->code) == BPF_LD &&
+		    (BPF_MODE(insn->code) == BPF_ABS ||
+		     BPF_MODE(insn->code) == BPF_IND)) {
+			ret = visit_abnormal_return_insn(env, t);
+			if (ret)
+				return ret;
+		}
 		insn_sz = bpf_is_ldimm64(insn) ? 2 : 1;
 		return push_insn(t, t + insn_sz, FALLTHROUGH, env);
 	}

 	switch (BPF_OP(insn->code)) {
 	case BPF_EXIT:
 		return DONE_EXPLORING;

 	case BPF_CALL:
 		if (is_async_callback_calling_insn(insn))
 			/* Mark this call insn as a prune point to trigger
 			 * is_state_visited() check before call itself is
 			 * processed by __check_func_call(). Otherwise new
 			 * async state will be pushed for further exploration.
 			 */
 			mark_prune_point(env, t);
 		/* For functions that invoke callbacks it is not known how many times
 		 * callback would be called. Verifier models callback calling functions
 		 * by repeatedly visiting callback bodies and returning to origin call
 		 * instruction.
 		 * In order to stop such iteration verifier needs to identify when a
 		 * state identical some state from a previous iteration is reached.
 		 * Check below forces creation of checkpoint before callback calling
 		 * instruction to allow search for such identical states.
 		 */
 		if (is_sync_callback_calling_insn(insn)) {
 			mark_calls_callback(env, t);
 			mark_force_checkpoint(env, t);
 			mark_prune_point(env, t);
 			mark_jmp_point(env, t);
 		}
 		if (bpf_helper_call(insn)) {
 			const struct bpf_func_proto *fp;

 			ret = get_helper_proto(env, insn->imm, &fp);
 			/* If called in a non-sleepable context program will be
 			 * rejected anyway, so we should end up with precise
 			 * sleepable marks on subprogs, except for dead code
 			 * elimination.
 			 */
 			if (ret == 0 && fp->might_sleep)
 				mark_subprog_might_sleep(env, t);
 			if (bpf_helper_changes_pkt_data(insn->imm))
 				mark_subprog_changes_pkt_data(env, t);
 			if (insn->imm == BPF_FUNC_tail_call) {
-				ret = visit_tailcall_insn(env, t);
+				ret = visit_abnormal_return_insn(env, t);
 				if (ret)
 					return ret;
 			}
 		} else if (insn->src_reg == BPF_PSEUDO_KFUNC_CALL) {
 			struct bpf_kfunc_call_arg_meta meta;

 			ret = fetch_kfunc_arg_meta(env, insn->imm, insn->off, &meta);
 			if (ret == 0 && is_iter_next_kfunc(&meta)) {
 				mark_prune_point(env, t);
 				/* Checking and saving state checkpoints at iter_next() call
 				 * is crucial for fast convergence of open-coded iterator loop
 				 * logic, so we need to force it. If we don't do that,
 				 * is_state_visited() might skip saving a checkpoint, causing
 				 * unnecessarily long sequence of not checkpointed
 				 * instructions and jumps, leading to exhaustion of jump
 				 * history buffer, and potentially other undesired outcomes.
 				 * It is expected that with correct open-coded iterators
 				 * convergence will happen quickly, so we don't run a risk of
 				 * exhausting memory.
 				 */
 				mark_force_checkpoint(env, t);
 			}
 			/* Same as helpers, if called in a non-sleepable context
 			 * program will be rejected anyway, so we should end up
 			 * with precise sleepable marks on subprogs, except for
 			 * dead code elimination.
 			 */
 			if (ret == 0 && is_kfunc_sleepable(&meta))
 				mark_subprog_might_sleep(env, t);
 			if (ret == 0 && is_kfunc_pkt_changing(&meta))
 				mark_subprog_changes_pkt_data(env, t);
 		}
 		return visit_func_call_insn(t, insns, env, insn->src_reg == BPF_PSEUDO_CALL);

 	case BPF_JA:
 		if (BPF_SRC(insn->code) == BPF_X)
 			return visit_gotox_insn(t, env);

 		if (BPF_CLASS(insn->code) == BPF_JMP)
 			off = insn->off;
 		else
 			off = insn->imm;

 		/* unconditional jump with single edge */
 		ret = push_insn(t, t + off + 1, FALLTHROUGH, env);
 		if (ret)
 			return ret;

 		mark_prune_point(env, t + off + 1);
 		mark_jmp_point(env, t + off + 1);

 		return ret;

 	default:
 		/* conditional jump with two edges */
 		mark_prune_point(env, t);
 		if (bpf_is_may_goto_insn(insn))
 			mark_force_checkpoint(env, t);

 		ret = push_insn(t, t + 1, FALLTHROUGH, env);
 		if (ret)
 			return ret;

 		return push_insn(t, t + insn->off + 1, BRANCH, env);
 	}
 }



